section.script:
// 
(function () {
  var DAY = document.getElementById('pf-day').value;

  function rpcWrite(woId, vals, cb) {
    fetch('/web/dataset/call_kw', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: {
        model: 'mrp.workorder', method: 'write', args: [[woId], vals], kwargs: {}
      }})
    }).then(function (r) { return r.json(); }).then(function (data) {
      if (data.error) { cb(false, data.error.data && data.error.data.message || data.error.message); }
      else { cb(true); }
    }).catch(function (e) { cb(false, String(e)); });
  }

  function fmtUTC(ms) {
    var d = new Date(ms);
    function z(n) { return (n < 10 ? '0' : '') + n; }
    return d.getUTCFullYear() + '-' + z(d.getUTCMonth() + 1) + '-' + z(d.getUTCDate()) + ' ' + z(d.getUTCHours()) + ':' + z(d.getUTCMinutes()) + ':' + z(d.getUTCSeconds());
  }

  function toast(txt) {
    var t = document.createElement('div');
    t.textContent = txt;
    t.style.cssText = 'position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:#2d6a6f;color:#fff;padding:8px 16px;border-radius:8px;z-index:999;font-size:13px;box-shadow:0 4px 12px rgba(0,0,0,.3);';
    document.body.appendChild(t);
    setTimeout(function () { t.remove(); }, 4500);
  }

  // Pastille ✓ = terminer l'ordre de travail
  document.querySelectorAll('.pf-done').forEach(function (b) {
    b.addEventListener('click', function (ev) {
      ev.preventDefault(); ev.stopPropagation();
      if (!confirm('Terminer cette opération ?')) { return; }
      var woId = parseInt(b.closest('.pf-card').getAttribute('data-id'));
      fetch('/web/dataset/call_kw', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { model: 'mrp.workorder', method: 'button_finish', args: [[woId]], kwargs: {} } })
      }).then(function (r) { return r.json(); }).then(function (d) {
        if (d.error) { alert('Échec : ' + (d.error.data && d.error.data.message || d.error.message)); }
        else { window.location.reload(); }
      }).catch(function (e) { alert('Échec : ' + e); });
    });
  });

  var tpl = document.getElementById('pf-emp-tpl');
  document.querySelectorAll('select.pf-op').forEach(function (sel) {
    sel.innerHTML = tpl.innerHTML;
    sel.value = sel.getAttribute('data-op') || '';
    sel.addEventListener('click', function (ev) { ev.preventDefault(); ev.stopPropagation(); });
    sel.addEventListener('change', function () {
      var woId = parseInt(sel.closest('.pf-card').getAttribute('data-id'));
      var v = sel.value;
      rpcWrite(woId, { employee_assigned_ids: v ? [[6, false, [parseInt(v)]]] : [[5]] }, function (ok, msg) {
        sel.style.outline = ok ? '2px solid #2E9E5B' : '2px solid #D33';
        if (!ok) alert('Échec affectation opérateur : ' + msg);
      });
    });
  });

  // Clic sur le n° de commande : lien natif (rien à faire), conservé pour cohérence

  var selected = null, bar = null, dragged = null;
  function clearSel() {
    if (selected) { selected.style.boxShadow = ''; selected = null; }
    if (bar) { bar.parentNode && bar.parentNode.removeChild(bar); bar = null; }
    var cols = document.querySelectorAll('.pf-col');
    for (var i = 0; i < cols.length; i++) { cols[i].style.outline = ''; }
  }
  function applyDrop(card, col) {
    var empId = parseInt(col.getAttribute('data-emp'));
    if (empId === -1) { var uprod = parseInt(card.getAttribute('data-prod')); if (!(uprod > 0)) { toast('OF introuvable, impossible de déplanifier.'); clearSel(); return; } if (!confirm('Déplanifier tout l’OF ? Toutes ses opérations repasseront en « À planifier ».')) { clearSel(); return; } fetch('/web/dataset/call_kw', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{model:'mrp.production', method:'button_unplan', args:[[uprod]], kwargs:{}}}) }).then(function(r){return r.json();}).then(function(d){ if(d.error){ alert('Échec déplanification : ' + (d.error.data && d.error.data.message || d.error.message)); clearSel(); } else { window.location.reload(); } }).catch(function(e){ alert('Échec : ' + e); clearSel(); }); return; }
    var woId = parseInt(card.getAttribute('data-id'));
    var dur = parseFloat(card.getAttribute('data-dur')) || 60;
    var p = DAY.split('-');
    var startMs = Date.UTC(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2]), 6, 0, 0);
    var vals = { date_start: fmtUTC(startMs), date_finished: fmtUTC(startMs + dur * 60000),
                 employee_assigned_ids: empId > 0 ? [[6, false, [empId]]] : [[5]] };
    var origin = card.parentNode;
    col.appendChild(card);
    clearSel();
    rpcWrite(woId, vals, function (ok, msg) {
      if (!ok) { origin.appendChild(card); alert('Échec : ' + msg); }
    });
  }
  function selectCard(card) {
    clearSel();
    selected = card;
    card.style.boxShadow = '0 0 0 3px #3B82F6';
    var cols = document.querySelectorAll('.pf-col');
    for (var i = 0; i < cols.length; i++) {
      if (parseInt(cols[i].getAttribute('data-emp')) > -1) { cols[i].style.outline = '2px dashed #3B82F6'; }
    }
    bar = document.createElement('div');
    bar.style.cssText = 'position:fixed;bottom:0;left:0;right:0;background:#1F2937;color:#fff;padding:12px 16px;z-index:998;font-size:15px;display:flex;justify-content:space-between;align-items:center;gap:10px;';
    var span = document.createElement('span');
    span.textContent = 'Touchez un opérateur pour lui affecter cette opération';
    var btn = document.createElement('button');
    btn.textContent = 'Annuler';
    btn.className = 'btn btn-sm btn-outline-light';
    btn.addEventListener('click', clearSel);
    bar.appendChild(span); bar.appendChild(btn);
    document.body.appendChild(bar);
  }
  function valsForTarget(tid, card) {
    var dur = parseFloat(card.getAttribute('data-dur')) || 60;
    var p = DAY.split('-');
    var s = Date.UTC(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2]), 6, 0, 0);
    return { date_start: fmtUTC(s), date_finished: fmtUTC(s + dur * 60000),
             employee_assigned_ids: tid > 0 ? [[6, false, [tid]]] : [[5]] };
  }
  var sheet = null;
  function closeSheet() { if (sheet) { sheet.parentNode && sheet.parentNode.removeChild(sheet); sheet = null; } }
  function openSheet(card) {
    closeSheet();
    sheet = document.createElement('div');
    sheet.style.cssText = 'position:fixed;left:0;right:0;bottom:0;background:#1F2937;color:#fff;z-index:999;padding:12px;max-height:65vh;overflow:auto;border-radius:12px 12px 0 0;box-shadow:0 -4px 16px rgba(0,0,0,.4);';
    var h = document.createElement('div');
    h.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;';
    var ttl = document.createElement('strong'); ttl.textContent = 'Affecter à quel opérateur ?';
    var x = document.createElement('button'); x.textContent = 'Annuler'; x.className = 'btn btn-sm btn-outline-light';
    x.addEventListener('click', closeSheet);
    h.appendChild(ttl); h.appendChild(x); sheet.appendChild(h);
    var grid = document.createElement('div');
    grid.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:8px;';
    var tgts = document.querySelectorAll('.pf-target');
    for (var i = 0; i < tgts.length; i++) {
      (function (t) {
        var b = document.createElement('button');
        b.className = 'btn btn-light'; b.style.cssText = 'font-size:13px;padding:10px 6px;';
        b.textContent = t.textContent;
        b.addEventListener('click', function () {
          var woId = parseInt(card.getAttribute('data-id'));
          rpcWrite(woId, valsForTarget(parseInt(t.getAttribute('data-tid')), card), function (ok, msg) {
            if (ok) { window.location.reload(); } else { alert('Échec : ' + msg); }
          });
          closeSheet();
        });
        grid.appendChild(b);
      })(tgts[i]);
    }
    sheet.appendChild(grid);
    document.body.appendChild(sheet);
  }

  var cards = document.querySelectorAll('.pf-card');
  for (var ci = 0; ci < cards.length; ci++) {
    (function (card) {
      card.addEventListener('click', function (ev) {
        if (ev.target.closest('a') || ev.target.closest('select')) { return; }
        ev.stopPropagation();
        if (card.getAttribute('data-lock') !== '0') { return; }
        if (window.innerWidth < 768) { openSheet(card); } else if (selected === card) { clearSel(); } else { selectCard(card); }
      });
      if (card.getAttribute('data-lock') === '0') {
        card.setAttribute('draggable', 'true');
        card.addEventListener('dragstart', function () { dragged = card; card.style.opacity = '0.4'; });
        card.addEventListener('dragend', function () { card.style.opacity = '1'; });
      }
    })(cards[ci]);
  }
  var cols = document.querySelectorAll('.pf-col');
  for (var co = 0; co < cols.length; co++) {
    (function (col) {
      col.addEventListener('click', function () {
        if (selected) { applyDrop(selected, col); }
      });
      col.addEventListener('dragover', function (ev) { ev.preventDefault(); col.style.boxShadow = 'inset 0 0 0 2px #3B82F6'; });
      col.addEventListener('dragleave', function () { col.style.boxShadow = ''; });
      col.addEventListener('drop', function (ev) {
        ev.preventDefault(); col.style.boxShadow = '';
        if (dragged) { applyDrop(dragged, col); dragged = null; }
      });
    })(cols[co]);
  }
  function sizeBoard() {
    var el = document.getElementById('pf-board');
    if (!el) { return; }
    var r = el.getBoundingClientRect();
    var h = window.innerHeight - r.top - 8;
    if (h > 200) { el.style.height = h + 'px'; }
  }
  sizeBoard();
  window.addEventListener('resize', sizeBoard);
  setInterval(function () {
    var modals = document.querySelectorAll('.modal, .o_dialog');
    for (var i = 0; i < modals.length; i++) {
      if ((modals[i].textContent || '').indexOf('Could not start interaction') !== -1) {
        var btns = modals[i].querySelectorAll('button');
        for (var j = 0; j < btns.length; j++) {
          if (/fermer|close/i.test(btns[j].textContent || '')) { btns[j].click(); }
        }
      }
    }
  }, 1200);
})();
//
